/* GitHub Theme — Tailwind v3 (hex) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* GitHub Theme - Official GitHub brand colors (Primer Design System)  */

  /* Light mode (:root) */
  :root {
    --background: 255 255 255;
    --foreground: 28 34 41;
    --card: 247 249 250;
    --card-foreground: 28 34 41;
    --popover: 255 255 255;
    --popover-foreground: 28 34 41;
    --primary: 16 120 35;
    --primary-foreground: 255 255 255;
    --secondary: 239 242 245;
    --secondary-foreground: 40 47 53;
    --muted: 244 245 247;
    --muted-foreground: 93 100 108;
    --accent: 48 114 223;
    --accent-foreground: 255 255 255;
    --destructive: 204 39 46;
    --destructive-foreground: 255 255 255;
    --border: 208 213 217;
    --input: 244 245 247;
    --ring: 48 114 223;
    --chart-1: 16 120 35;
    --chart-2: 48 114 223;
    --chart-3: 183 110 199;
    --chart-4: 221 131 100;
    --chart-5: 0 149 131;
    --radius: 0.375rem;
    --sidebar: 244 245 247;
    --sidebar-foreground: 28 34 41;
    --sidebar-primary: 16 120 35;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 239 242 245;
    --sidebar-accent-foreground: 40 47 53;
    --sidebar-border: 208 213 217;
    --sidebar-ring: 48 114 223;
    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
    --font-serif: ui-serif, Georgia, serif;
    --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    --shadow-color: 41 49 61;
    --shadow-opacity: 0.06;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: -0.01em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 0 0px hsl(215 20% 20% / 0.04);
    --shadow-xs: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 1px 3px 0px hsl(215 20% 20% / 0.06);
    --shadow-sm: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
    --shadow: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 2px 4px 0px hsl(215 20% 20% / 0.08);
    --shadow-md: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 4px 8px 0px hsl(215 20% 20% / 0.1);
    --shadow-lg: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 8px 16px 0px hsl(215 20% 20% / 0.1);
    --shadow-xl: 0 1px 0 0px hsl(215 20% 20% / 0.04), 0 12px 28px 0px hsl(215 20% 20% / 0.12);
    --shadow-2xl: 0 24px 48px 0px hsl(215 20% 20% / 0.2);
    --tracking-normal: -0.01em;
  }

  /* Dark mode - #0D1117 is GitHub's signature dark background */
  .dark {
    --background: 8 12 16;
    --foreground: 201 206 212;
    --card: 14 18 23;
    --card-foreground: 201 206 212;
    --popover: 18 23 27;
    --popover-foreground: 201 206 212;
    --primary: 39 135 51;
    --primary-foreground: 255 255 255;
    --secondary: 22 27 32;
    --secondary-foreground: 185 190 196;
    --muted: 19 22 26;
    --muted-foreground: 117 123 129;
    --accent: 48 114 223;
    --accent-foreground: 255 255 255;
    --destructive: 215 71 69;
    --destructive-foreground: 255 255 255;
    --border: 42 46 51;
    --input: 14 18 23;
    --ring: 48 114 223;
    --chart-1: 39 135 51;
    --chart-2: 48 114 223;
    --chart-3: 196 128 212;
    --chart-4: 238 147 115;
    --chart-5: 0 166 146;
    --radius: 0.375rem;
    --sidebar: 5 8 11;
    --sidebar-foreground: 201 206 212;
    --sidebar-primary: 39 135 51;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 22 27 32;
    --sidebar-accent-foreground: 185 190 196;
    --sidebar-border: 42 46 51;
    --sidebar-ring: 48 114 223;
    --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif;
    --font-serif: ui-serif, Georgia, serif;
    --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.4;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: -0.01em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 0 0 1px hsl(0 0% 0% / 0.3);
    --shadow-xs: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 1px 3px 0px hsl(0 0% 0% / 0.3);
    --shadow-sm: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
    --shadow: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 2px 4px 0px hsl(0 0% 0% / 0.4);
    --shadow-md: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 4px 8px 0px hsl(0 0% 0% / 0.4);
    --shadow-lg: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 8px 16px 0px hsl(0 0% 0% / 0.4);
    --shadow-xl: 0 0 0 1px hsl(0 0% 0% / 0.3), 0 12px 28px 0px hsl(0 0% 0% / 0.5);
    --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
  }

}
